import { useState, useEffect, useCallback } from "react";
import { supabase } from "./supabase.js";

const VISIT_SLOTS = ["11:00", "13:00", "15:00", "17:00"];
const HOSPITAL = {
  name: "Hôpital Michallon · CHU Grenoble Alpes",
  address: "Bd de la Chantourne, 38700 La Tronche",
  room: "Chambre 140",
  mapsUrl: "https://maps.google.com/?q=H%C3%B4pital+Michallon+CHU+Grenoble+Alpes+La+Tronche",
};

const PHOTO = "data:image/jpeg;base64,";

const RULES = [
  { icon: "⏱️", text: "15 à 20 minutes maximum par visite" },
  { icon: "👥", text: "2 personnes maximum par créneau" },
  { icon: "🕐", text: "Créneaux : 11h, 13h, 15h, 17h" },
  { icon: "⏳", text: "Au moins 2h entre chaque visite" },
  { icon: "🌙", text: "1 personne peut rester la nuit" },
  
  ];

const C = {
  bg: "#0D1B2E", card: "#112240", border: "#1E3A5F",
  accent: "#2E75B6", orange: "#C45911", gold: "#f0b429",
  text: "#e8edf5", muted: "#7a8fa6", success: "#3ecf8e", danger: "#e94560",
};

function toISO(d) { return d.toISOString().split("T")[0]; }
function toFr(d) {
  return d.toLocaleDateString("fr-FR", { weekday: "long", day: "numeric", month: "long" });
}
function generateDays(count = 28) {
  const days = [];
  const today = new Date(); today.setHours(0,0,0,0);
  for (let i = 0; i < count; i++) {
    const d = new Date(today); d.setDate(today.getDate() + i); days.push(d);
  }
  return days;
}
function googleCalendarUrl({ title, date, startH, endH, description }) {
  const pad = n => String(n).padStart(2,"0");
  const d = date.replace(/-/g,"");
  const start = d + "T" + pad(startH) + "0000";
  const end = d + "T" + pad(endH) + "0000";
  return `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent(title)}&dates=${start}/${end}&details=${encodeURIComponent(description)}&location=${encodeURIComponent(HOSPITAL.address)}`;
}

const S = {
  app: { minHeight:"100vh", background:C.bg, color:C.text, fontFamily:"'DM Sans', system-ui, sans-serif", paddingBottom:80 },
  header: { background:"linear-gradient(160deg, #0D1B2E 0%, #1F3864 100%)", borderBottom:`1px solid ${C.border}`, padding:"28px 24px 0", textAlign:"center" },
  photoWrap: { width:88, height:88, borderRadius:"50%", border:`3px solid ${C.gold}`, overflow:"hidden", margin:"0 auto 14px", boxShadow:"0 0 0 4px rgba(240,180,41,0.15)" },
  photo: { width:"100%", height:"100%", objectFit:"cover" },
  h1: { fontFamily:"'Playfair Display', Georgia, serif", fontSize:"1.8rem", fontWeight:700, color:"#fff", margin:"0 0 4px" },
  subtitle: { color:C.gold, fontSize:"0.75rem", letterSpacing:"0.14em", textTransform:"uppercase", fontWeight:500, margin:"0 0 4px" },
  mapLink: { display:"inline-flex", alignItems:"center", gap:5, color:C.accent, fontSize:"0.78rem", textDecoration:"none", marginBottom:6 },
  tabs: { display:"flex", justifyContent:"center", gap:0, margin:"16px auto 0", maxWidth:380, borderTop:`1px solid ${C.border}` },
  tab: (a) => ({ flex:1, padding:"12px 8px", background:"transparent", color: a ? "#fff" : C.muted, border:"none", borderBottom: a ? `2px solid ${C.accent}` : "2px solid transparent", cursor:"pointer", fontSize:"0.78rem", fontWeight:600, letterSpacing:"0.06em", textTransform:"uppercase", fontFamily:"'DM Sans', system-ui, sans-serif", transition:"all 0.2s" }),
  container: { maxWidth:720, margin:"24px auto 0", padding:"0 16px" },
  dayCard: { background:C.card, border:`1px solid ${C.border}`, borderRadius:12, marginBottom:12, overflow:"hidden" },
  dayHeader: { background:"rgba(31,56,100,0.5)", padding:"10px 16px", borderBottom:`1px solid ${C.border}`, display:"flex", alignItems:"center", justifyContent:"space-between" },
  dayTitle: { fontSize:"0.9rem", fontWeight:600, color:"#fff", textTransform:"capitalize", margin:0 },
  grid: { display:"grid", gridTemplateColumns:"repeat(auto-fill, minmax(145px, 1fr))", gap:8, padding:12 },
  slotCard: (full) => ({ background: full ? "rgba(233,69,96,0.07)" : "rgba(46,117,182,0.08)", border:`1px solid ${full ? "rgba(233,69,96,0.3)" : C.border}`, borderRadius:8, padding:"10px 10px 8px", cursor: full ? "default" : "pointer" }),
  slotTime: { fontFamily:"'Playfair Display', serif", fontSize:"1.2rem", fontWeight:700, color:C.gold },
  slotMeta: { fontSize:"0.68rem", color:C.muted, textTransform:"uppercase", letterSpacing:"0.07em", marginTop:1 },
  occupants: { marginTop:6, display:"flex", flexDirection:"column", gap:2 },
  occupant: { fontSize:"0.78rem", color:C.success },
  bookBtn: (full) => ({ marginTop:8, width:"100%", padding:"7px 0", background: full ? "transparent" : C.accent, color: full ? C.muted : "#fff", border: full ? `1px solid ${C.border}` : "none", borderRadius:5, cursor: full ? "default" : "pointer", fontSize:"0.73rem", fontWeight:600, fontFamily:"'DM Sans', system-ui, sans-serif" }),
  nightRow: (full) => ({ margin:"0 12px 12px", background: full ? "rgba(233,69,96,0.07)" : "rgba(240,180,41,0.07)", border:`1px solid ${full ? "rgba(233,69,96,0.3)" : "rgba(240,180,41,0.3)"}`, borderRadius:8, padding:"12px 14px", display:"flex", alignItems:"center", justifyContent:"space-between", gap:10, flexWrap:"wrap" }),
  nightLabel: { fontSize:"0.86rem", fontWeight:600, color:C.gold },
  nightMeta: { fontSize:"0.72rem", color:C.muted, marginTop:2 },
  nightOcc: (full) => ({ fontSize:"0.8rem", color: full ? C.muted : C.success, marginTop:3 }),
  nightBtn: (full) => ({ padding:"9px 16px", background: full ? "transparent" : C.gold, color: full ? C.muted : "#0D1B2E", border: full ? `1px solid ${C.border}` : "none", borderRadius:7, cursor: full ? "default" : "pointer", fontWeight:700, fontSize:"0.8rem", fontFamily:"'DM Sans', system-ui, sans-serif", whiteSpace:"nowrap" }),
  overlay: { position:"fixed", inset:0, background:"rgba(0,0,0,0.8)", display:"flex", alignItems:"center", justifyContent:"center", zIndex:100, padding:16 },
  modal: { background:C.card, border:`1px solid ${C.accent}`, borderRadius:14, padding:"24px 20px", width:"100%", maxWidth:380 },
  modalTitle: { fontFamily:"'Playfair Display', serif", fontSize:"1.2rem", fontWeight:700, margin:"0 0 3px", color:"#fff" },
  modalSub: { fontSize:"0.82rem", color:C.muted, margin:"0 0 16px" },
  input: { width:"100%", padding:"10px 12px", background:C.bg, border:`1px solid ${C.border}`, borderRadius:7, color:C.text, fontSize:"0.93rem", fontFamily:"'DM Sans', system-ui, sans-serif", boxSizing:"border-box", marginBottom:8, outline:"none" },
  btnRow: { display:"flex", gap:8, marginTop:4 },
  btnPrimary: { flex:1, padding:11, background:C.accent, color:"#fff", border:"none", borderRadius:8, cursor:"pointer", fontWeight:600, fontSize:"0.86rem", fontFamily:"'DM Sans', system-ui, sans-serif" },
  btnSecondary: { flex:1, padding:11, background:"transparent", color:C.muted, border:`1px solid ${C.border}`, borderRadius:8, cursor:"pointer", fontWeight:500, fontSize:"0.86rem", fontFamily:"'DM Sans', system-ui, sans-serif" },
  gcalBtn: { display:"block", width:"100%", marginTop:10, padding:"11px 0", background:"rgba(52,168,83,0.15)", color:"#3da85e", border:"1px solid rgba(52,168,83,0.4)", borderRadius:8, cursor:"pointer", fontWeight:600, fontSize:"0.84rem", textAlign:"center", textDecoration:"none", fontFamily:"'DM Sans', system-ui, sans-serif" },
  successBox: { textAlign:"center", padding:"8px 0 4px" },
  successIcon: { fontSize:"2.5rem", marginBottom:6 },
  successTitle: { fontSize:"1.1rem", fontWeight:700, color:C.success, margin:"0 0 4px" },
  successSub: { fontSize:"0.82rem", color:C.muted, margin:0 },
  toast: { position:"fixed", bottom:24, left:"50%", transform:"translateX(-50%)", background:C.success, color:"#fff", padding:"11px 20px", borderRadius:8, fontWeight:600, fontSize:"0.88rem", zIndex:200, whiteSpace:"nowrap", boxShadow:"0 4px 20px rgba(0,0,0,0.4)" },
  infoCard: { background:C.card, border:`1px solid ${C.border}`, borderRadius:12, padding:"16px 18px", marginBottom:12 },
  ruleRow: { display:"flex", gap:12, alignItems:"flex-start", marginBottom:10 },
  ruleIcon: { fontSize:"1.2rem", flexShrink:0 },
  ruleText: { fontSize:"0.88rem", color:C.text, lineHeight:1.5 },
};

export default function App() {
  const [reservations, setReservations] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [modal, setModal] = useState(null);
  const [confirmed, setConfirmed] = useState(null);
  const [prenom, setPrenom] = useState("");
  const [nom, setNom] = useState("");
  const [tel, setTel] = useState("");
  const [saving, setSaving] = useState(false);
  const [tab, setTab] = useState("visits");
  const [toast, setToast] = useState("");
  const days = generateDays(28);

  const load = useCallback(async () => {
    try {
      const { data, error: err } = await supabase.from("reservations").select("*");
      if (err) throw err;
      setReservations(data || []);
      setError(null);
    } catch (e) { setError(e.message); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => {
    load();
    const ch = supabase.channel("res").on("postgres_changes", { event:"*", schema:"public", table:"reservations" }, load).subscribe();
    return () => supabase.removeChannel(ch);
  }, [load]);

  function showToast(msg) { setToast(msg); setTimeout(() => setToast(""), 3000); }

  function getVisitors(dateISO, slot) {
    return reservations.filter(r => r.date === dateISO && r.creneau === slot && r.type === "Visite");
  }
  function getNight(dateISO) {
    return reservations.find(r => r.date === dateISO && r.type === "Nuit");
  }

  function openModal(type, date, slot = null) {
    setModal({ type, date, slot });
    setConfirmed(null);
    setPrenom(""); setNom(""); setTel("");
  }

  async function handleBook() {
    if (!prenom.trim()) return;
    setSaving(true);
    try {
      const { error: err } = await supabase.from("reservations").insert({
        date: modal.date,
        creneau: modal.slot || "Nuit",
        prenom: prenom.trim(),
        nom: nom.trim(),
        type: modal.type === "night" ? "Nuit" : "Visite",
      });
      if (err) throw err;
      const isNight = modal.type === "night";
      const startH = isNight ? 18 : parseInt(modal.slot);
      const endH = isNight ? 11 : startH + 1;
      const gcal = googleCalendarUrl({
        title: `Visite Rose-Marie · ${HOSPITAL.room}`,
        date: modal.date,
        startH, endH,
        description: `Visite à ${HOSPITAL.name} - ${HOSPITAL.room}\nDurée : 15-20 min max\n2 personnes max par créneau`,
      });
      setConfirmed({ prenom: prenom.trim(), gcal, isNight, slot: modal.slot, date: modal.date });
      load();
    } catch (e) { showToast("Erreur : " + e.message); }
    finally { setSaving(false); }
  }

  if (loading) return <div style={S.app}><div style={{textAlign:"center",padding:"60px 0",color:C.muted}}>Chargement…</div></div>;

  return (
    <div style={S.app}>
      <div style={S.header}>
        <div style={S.photoWrap}><img src={PHOTO} alt="Rose-Marie" style={S.photo} /></div>
        <h1 style={S.h1}>Visites Rose-Marie</h1>
        <p style={S.subtitle}>{HOSPITAL.room} · CHU Grenoble</p>
        <a href={HOSPITAL.mapsUrl} target="_blank" rel="noopener noreferrer" style={S.mapLink}>
          📍 {HOSPITAL.address}
        </a>
        <div style={S.tabs}>
          {[["visits","🕐 Visites"],["nights","🌙 Nuitées"],["info","ℹ️ Infos"]].map(([id,label]) => (
            <button key={id} style={S.tab(tab===id)} onClick={() => setTab(id)}>{label}</button>
          ))}
        </div>
      </div>

      <div style={S.container}>
        {error && <div style={{color:C.danger,textAlign:"center",padding:"20px 0",fontSize:"0.88rem"}}>{error}</div>}

        {tab === "info" && (
          <div style={S.infoCard}>
            <h2 style={{fontFamily:"'Playfair Display',serif",fontSize:"1.15rem",margin:"0 0 16px",color:"#fff"}}>Règles des visites</h2>
            {RULES.map((r,i) => (
              <div key={i} style={S.ruleRow}>
                <span style={S.ruleIcon}>{r.icon}</span>
                <span style={S.ruleText}>{r.text}</span>
              </div>
            ))}
            <div style={{marginTop:16,padding:"12px 14px",background:"rgba(46,117,182,0.1)",borderRadius:8,border:`1px solid ${C.border}`}}>
              <div style={{fontSize:"0.82rem",fontWeight:600,color:C.accent,marginBottom:4}}>📍 Adresse</div>
              <div style={{fontSize:"0.85rem",color:C.text}}>{HOSPITAL.name}</div>
              <div style={{fontSize:"0.85rem",color:C.muted}}>{HOSPITAL.address}</div>
              <a href={HOSPITAL.mapsUrl} target="_blank" rel="noopener noreferrer" style={{display:"inline-block",marginTop:8,fontSize:"0.8rem",color:C.accent}}>Ouvrir dans Google Maps →</a>
            </div>
          </div>
        )}

        {tab === "visits" && days.map(day => {
          const iso = toISO(day);
          const isToday = iso === toISO(new Date());
          return (
            <div key={iso} style={S.dayCard}>
              <div style={S.dayHeader}>
                <span style={S.dayTitle}>{isToday ? "📍 " : ""}{toFr(day)}</span>
                <span style={{fontSize:"0.7rem",color:C.muted}}>4 créneaux · 2 places</span>
              </div>
              <div style={S.grid}>
                {VISIT_SLOTS.map(slot => {
                  const occ = getVisitors(iso, slot);
                  const full = occ.length >= 2;
                  return (
                    <div key={slot} style={S.slotCard(full)} onClick={!full ? () => openModal("visit", iso, slot) : undefined}>
                      <div style={S.slotTime}>{slot}</div>
                      <div style={S.slotMeta}>{full ? "Complet" : `${2-occ.length} place${2-occ.length>1?"s":""} libre${2-occ.length>1?"s":""}`}</div>
                      <div style={S.occupants}>
                        {occ.map(r => <div key={r.id} style={S.occupant}>● {r.prenom} {r.nom}</div>)}
                      </div>
                      <button style={S.bookBtn(full)} disabled={full} onClick={!full ? e => { e.stopPropagation(); openModal("visit",iso,slot); } : undefined}>
                        {full ? "Complet" : "S'inscrire"}
                      </button>
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}

        {tab === "nights" && days.map(day => {
          const iso = toISO(day);
          const isToday = iso === toISO(new Date());
          const occ = getNight(iso);
          const full = !!occ;
          return (
            <div key={iso} style={S.dayCard}>
              <div style={S.dayHeader}>
                <span style={S.dayTitle}>{isToday ? "📍 " : ""}{toFr(day)}</span>
              </div>
              <div style={S.nightRow(full)}>
                <div>
                  <div style={S.nightLabel}>🌙 Nuit</div>
                  <div style={S.nightMeta}>18h00 → 11h00 · 1 personne max</div>
                  <div style={S.nightOcc(full)}>{occ ? `● ${occ.prenom} ${occ.nom}` : "Disponible"}</div>
                </div>
                <button style={S.nightBtn(full)} disabled={full} onClick={!full ? () => openModal("night",iso) : undefined}>
                  {full ? "Occupé" : "Réserver"}
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {modal && (
        <div style={S.overlay} onClick={() => setModal(null)}>
          <div style={S.modal} onClick={e => e.stopPropagation()}>
            {!confirmed ? (
              <>
                <div style={S.modalTitle}>{modal.type==="night" ? "🌙 Réserver une nuit" : `🕐 Visite ${modal.slot}`}</div>
                <p style={S.modalSub}>{toFr(new Date(modal.date+"T12:00:00"))} · {modal.type==="night" ? "18h → 11h" : "15-20 min max"}</p>
                <input style={S.input} type="text" placeholder="Prénom *" value={prenom} onChange={e=>setPrenom(e.target.value)} onKeyDown={e=>e.key==="Enter"&&handleBook()} autoFocus />
                <input style={S.input} type="text" placeholder="Nom" value={nom} onChange={e=>setNom(e.target.value)} onKeyDown={e=>e.key==="Enter"&&handleBook()} />
                <input style={S.input} type="tel" placeholder="Téléphone" value={tel} onChange={e=>setTel(e.target.value)} onKeyDown={e=>e.key==="Enter"&&handleBook()} />
                <div style={S.btnRow}>
                  <button style={S.btnSecondary} onClick={()=>setModal(null)}>Annuler</button>
                  <button style={{...S.btnPrimary,opacity:(!prenom.trim()||saving)?0.5:1}} onClick={handleBook} disabled={!prenom.trim()||saving}>
                    {saving ? "Envoi…" : "Confirmer"}
                  </button>
                </div>
              </>
            ) : (
              <>
                <div style={S.successBox}>
                  <div style={S.successIcon}>🎉</div>
                  <div style={S.successTitle}>Merci {confirmed.prenom} !</div>
                  <p style={S.successSub}>Ta visite est enregistrée.<br/>Rose-Marie sera heureuse de te voir 💛</p>
                </div>
                <a href={confirmed.gcal} target="_blank" rel="noopener noreferrer" style={S.gcalBtn}>
                  📅 Ajouter à Google Calendar
                </a>
                <div style={S.btnRow}>
                  <button style={{...S.btnSecondary,marginTop:8}} onClick={()=>setModal(null)}>Fermer</button>
                </div>
              </>
            )}
          </div>
        </div>
      )}

      {toast && <div style={S.toast}>{toast}</div>}
    </div>
  );
}
